// Helper functions
export function getPlatformsByUrl(url: string): PageData | undefined {
  const cleanUrl = url.replace(/^\/+|\/+$/g, '');
  return platformsData.pages.find(page => 
    page.url === url || 
    page.url === `/${url}` ||
    page.url.replace(/^\/+|\/+$/g, '') === cleanUrl
  );
}

export function getPlatformsByKeyword(keyword: string): PageData[] {
  return platformsData.pages.filter(page =>
    page.metadata.primaryKeyword === keyword ||
    page.metadata.secondaryKeywords.includes(keyword)
  );
}

export default platformsData;
